import React, {Component} from "react";
import axios from "axios";
import {Link, Redirect} from "react-router-dom";
import {SERVER_HOST} from "../config/global_constants";

class Login extends Component {
    constructor(props) {
        super(props);
        this.state = {
            loginEmail: '',
            loginPassword: '',
            error: '',
            isLoggedIn: false,
            redirectURL: "/MainPage",
        };
    }

    handleLogin = async (e) => {
        e.preventDefault();
        console.log('Login with:', this.state.loginEmail, this.state.loginPassword);

        try {
            const res = await axios.post(`${SERVER_HOST}/users/login`, {
                email: this.state.loginEmail,
                password: this.state.loginPassword
            });

            if (!res.data) {
                throw new Error("No response data received");
            }

            if (res.data.errorMessage) {
                console.log(res.data.errorMessage);
                this.setState({ errors: { general: res.data.errorMessage } });
                return;
            }

            console.log("User logged in");

            localStorage.setItem("name", res.data.name);
            localStorage.setItem("accessLevel", res.data.accessLevel);
            localStorage.setItem("token", res.data.token);

            this.setState({ isLoggedIn: true }, () => {
                if (res.data.redirectURL) {
                    window.location.href = res.data.redirectURL; // Redirect if needed
                }
            });

        } catch (error) {
            console.error('Login error:', error.response?.data || error.message);

            this.setState({
                errors: {
                    general: error.response?.data?.error || "Login failed. Please check your credentials."
                }
            });
        }
    };


    render() {
        if (this.state.isLoggedIn) {
            return <Redirect to={this.state.redirectURL}/>;
        }
        return (
            <div>
                <div className="login">
                    <div className="login-container">
                        {/* Login Form */}
                        <form onSubmit={this.handleLogin}>
                            <h2>Login</h2>
                            <div className="input-group">
                                <label>
                                    Email Address *
                                    <input
                                        type="email"
                                        value={this.state.loginEmail}
                                        onChange={e => this.setState({loginEmail: e.target.value})}
                                        required
                                    />
                                </label>
                                <label>
                                    Password *
                                    <input
                                        type="password"
                                        value={this.state.loginPassword}
                                        onChange={e => this.setState({loginPassword: e.target.value})}
                                        required
                                    />
                                </label>
                                <div>
                                    <input type="checkbox"/> Remember Me
                                </div>
                                <button type="submit">Log in</button>
                                <a href="#">Lost your password?</a>
                            </div>
                        </form>


                        {/* Additional Links */}
                        <div style={{marginLeft: 20}}>
                            <p>Don't have an account?</p>
                            <Link to="/Register">Register</Link>
                            <br/><br/>
                            <p>Or, sign in as Admin</p>
                            <Link to="/AdminLogin">Admin Login</Link>

                        </div>
                    </div>
                </div>
            </div>
        );
    }
}

export default Login;
